examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
/// The web's widths: narrow 44rem, content 72rem, wide 80rem.
private func containerWidth(_ size: String) -> CGFloat {
    switch size {
    case "narrow": 704
    case "wide": 1280
    default: 1152
    }
}
private func containerBlock(_ size: String, _ text: String) -> some View {
    Text(text)
        .monarchTextStyle(.body)
        .padding(12)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(theme.colors.bgMuted, in: RoundedRectangle(cornerRadius: theme.radius.md))
        .padding(.horizontal, theme.spacing.space4)
        .frame(maxWidth: containerWidth(size))
        .frame(maxWidth: .infinity)
}

